import java.util.function.IntPredicate;

public class Solution {
    // Invariante: a resposta está em [lo, hi]. O(log n) chamadas.
    static int primeiraRuim(int n, IntPredicate ehRuim) {
        int lo = 1, hi = n;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (ehRuim.test(mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
}

