import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.concurrent.atomic.AtomicInteger;

class SolutionTest {
    private static int rodar(int n, int primeira, AtomicInteger chamadas) {
        return Solution.primeiraRuim(n, v -> {
            chamadas.incrementAndGet();
            if (v < 1 || v > n) throw new IllegalArgumentException("versão fora do intervalo: " + v);
            return v >= primeira;
        });
    }

    @Test void pequenos() {
        for (int n = 1; n <= 40; n++) for (int p = 1; p <= n; p++) assertEquals(p, rodar(n, p, new AtomicInteger()));
    }

    @Test void semOverflow() {
        var c = new AtomicInteger();
        assertEquals(Integer.MAX_VALUE, rodar(Integer.MAX_VALUE, Integer.MAX_VALUE, c));
        assertTrue(c.get() <= 32, c.get() + " chamadas");
        assertEquals(Integer.MAX_VALUE - 1, rodar(Integer.MAX_VALUE, Integer.MAX_VALUE - 1, new AtomicInteger()));
    }

    @Test void poucasChamadas() {
        var c = new AtomicInteger();
        assertEquals(1_234_567, rodar(2_000_000_000, 1_234_567, c));
        assertTrue(c.get() <= 32, c.get() + " chamadas");
    }
}
